-- SINGLES2027 forms system, part 2 of 2: DATA.
-- Run AFTER part 1, as a data insert / in the SQL editor (not as a migration).
-- Adds the current sign-up form as the first form (published, on the home page)
-- and copies the submissions already received. Safe to run again (on conflict do nothing).

-- 4. The current sign-up form becomes the first form, published and on the home page
insert into public.forms (slug, title, template, status, is_home, draft, published, published_at)
values (
  'join-2027',
  'הצטרפות קהילות – אירוע ההכרויות 2027',
  'letter',
  'open',
  true,
  $def${"version":1,"texts":{"kicker":"ראשי קהילות ההכרויות והדייטינג,","headline":"הוזמנתם לקחת חלק בערב הכי רומנטי בישראל","year":"2027","title":"אירוע ההכרויות הגדול של ישראל","lead":"בשיתוף **כל קהילות הדייטינג וההכרויות בישראל**. אירוע היסטורי שייכנס ללוח השנה הקבוע של כולם: הפקת ענק שתתקיים **במקביל ברחבי הארץ**, ערב אחד שבו אלפי אנשים יפגשו, יכירו, ויתאהבו.","cities":"חיפה, נתניה, תל אביב, ראשון, ירושלים, באר שבע","citiesNote":"הרשימה הסופית של הערים המשתתפות תיקבע בהמשך","introTitle":"כתבו לנו קצת על הקהילה שלכם","introText":"מלאו את הטופס כדי להצטרף, אנחנו נהיה בקשר עם כל הפרטים החשובים.","consent":"אני מאשר/ת שהפרטים נכונים ומסכים/ה שצוות ההפקה ייצור איתי קשר בנוגע לאירוע.","submit":"אני בפנים, שלחו את הבקשה","doneTitle":"אתם בפנים!","doneText":"הבקשה התקבלה. צוות ההפקה יחזור אליך בקרוב עם השלבים הבאים.","closedTitle":"ההרשמה נסגרה","closedText":"תודה על ההתעניינות. ההרשמה דרך הטופס הזה הסתיימה.","footer":"נכתב ועוצב באהבה ע״י סיון הדרי וכרמל ברן בשיתוף עם ראשי קהילות הכרויות ודייטינג בישראל"},"sections":[{"id":"personal","title":"פרטים אישיים","subtitle":"איך נחזור אליך","fields":[{"id":"firstName","type":"short","label":"שם פרטי","required":true,"width":"half"},{"id":"lastName","type":"short","label":"שם משפחה","required":true,"width":"half"},{"id":"phone","type":"phone","label":"טלפון נייד","required":true,"width":"half","placeholder":"050-0000000"},{"id":"email","type":"email","label":"מייל","required":true,"width":"half","placeholder":"name@example.com"},{"id":"city","type":"short","label":"עיר מגורים","required":true,"width":"full","placeholder":"למשל תל אביב"}]},{"id":"community","title":"מאפייני הקהילה והעסק שלך","subtitle":"מי אתם ומה כבר עשיתם","fields":[{"id":"communityName","type":"short","label":"שם הקהילה","required":true,"width":"full"},{"id":"businessName","type":"short","label":"שם העסק","required":true,"width":"full"},{"id":"companyId","type":"short","label":"ח.פ.","width":"full","placeholder":"מספר ח.פ. / עוסק"},{"id":"logo1","type":"fil