"type":"number","label":"אחוז פתיחה בניוזלטר","width":"half","placeholder":"35","percent":true},{"id":"clickRate","type":"number","label":"אחוז הקלקה בניוזלטר","width":"half","placeholder":"4","percent":true},{"id":"totalExposure","type":"number","label":"חשיפה כללית משוערת בכל הערוצים","width":"full","placeholder":"למשל 40,000"}]},{"id":"partnersSection","title":"מנהלים ושותפים נוספים בקהילה","subtitle":"מי עוד בצוות","fields":[{"id":"partners","type":"people","label":"","width":"full"}]}],"listFields":["communityName","firstName","phone","city"]}$def$::jsonb,
