-- 5. Copy the submissions that already came in (the old table stays as a backup)
insert into public.form_responses (id, form_id, answers, labels, files, created_at)
select
  a.id,
  f.id,
  jsonb_build_object(
    'firstName', a.first_name, 'lastName', a.last_name, 'phone', a.phone, 'email', a.email,
    'city', a.city, 'communityName', a.community_name, 'businessName', a.business_name,
    'companyId', a.company_id, 'founded', a.founded, 'ageRange', a.age_range, 'purpose', a.purpose,
    'audience', a.audience, 'eventTypes', a.event_types, 'eventsCount', a.events_count,
    'attendance', a.attendance, 'fbGroup', a.fb_group, 'fbPage', a.fb_page,
    'instagram', a.instagram, 'whatsapp', a.whatsapp, 'newsletter', a.newsletter,
    'openRate', a.open_rate, 'clickRate', a.click_rate, 'totalExposure', a.total_exposure,
    'partners', a.partners
  ),
  (
    select coalesce(jsonb_object_agg(q ->> 'id', q ->> 'label'), '{}'::jsonb)
    from jsonb_array_elements(f.published -> 'sections') s,
         jsonb_array_elements(s -> 'fields') q
  ),
  jsonb_strip_nulls(jsonb_build_object(
    'logo1', case when a.logo1_path is not null then jsonb_build_array(a.logo1_path) end,
    'logo2', case when a.logo2_path is not null then jsonb_build_array(a.logo2_path) end
  )),
  a.created_at
from public.applications a
cross join public.forms f
where f.slug = 'join-2027'
on conflict (id) do nothing;
